class SerializationMethod(str, Enum):
    """Serialization format for file storage."""
    json = "json"
    pickle = "pickle"
    str = "str"
    binary = "binary"
    msgpack = "msgpack"
    numpy = "numpy"
    pandas_csv = "pandas_csv"
    pandas_parquet = "pandas_parquet"
    polars_csv = "polars_csv"
    polars_parquet = "polars_parquet"
    feather = "feather"
    torch = "torch"
    safetensors = "safetensors"

