def validate_imports(method: SerializationMethod) -> None:
    """Eagerly validate that required libraries are installed for a serialization method.

    Args:
        method: The serialization method to validate.

    Raises:
        ImportError: If required library is not installed, with install instructions.
    """
    match method:
        case SerializationMethod.json | SerializationMethod.pickle | SerializationMethod.str | SerializationMethod.binary:
            pass  # stdlib, always available
        case SerializationMethod.msgpack:
            import msgpack  # noqa: F401
        case SerializationMethod.numpy:
            import numpy  # noqa: F401
        case SerializationMethod.pandas_csv | SerializationMethod.pandas_parquet:
            import pandas  # noqa: F401
        case SerializationMethod.polars_csv | SerializationMethod.polars_parquet:
            import polars  # noqa: F401
        case SerializationMethod.feather:
            import pyarrow.feather  # noqa: F401
        case SerializationMethod.torch:
            import torch  # noqa: F401
        case SerializationMethod.safetensors:
            import safetensors.torch  # noqa: F401
